  row_exact_tile<T, K_SIZE, N_1, ROWS, RPS>(
      x, w1, scales1, biases1, y1, tile - start, row0, sg, sl);
  return;
}
start += TILES_1;
constexpr int TILES_2 = (N_2 + 2 * RPS - 1) / (2 * RPS);
if (tile < start + TILES_2) {
  row_exact_tile<T, K_SIZE, N_2, ROWS, RPS>(
      x, w2, scales2, biases2, y2, tile - start, row0, sg, sl);
  return;
}
start += TILES_2;
constexpr int TILES_3 = (N_3 + 2 * RPS - 1) / (2 * RPS);
if (tile < start + TILES_3) {
  row_exact_tile<T, K_SIZE, N_3, ROWS, RPS>(
      x, w3, scales3, biases3, y3, tile - start, row0, sg, sl);
  return;
}
start += TILES_3;

